function validate(input) {
  const [arr, n] = input;
  if (!Array.isArray(arr)) return 'arr must be an array.';
  if (!Number.isInteger(n) || n < 0 || n > 1000) return 'n must be an integer from 0 to 1000.';
  const stack = [[arr, 0]];
  while (stack.length) {
    const [items, depth] = stack.pop();
    for (const item of items) {
      if (Array.isArray(item)) {
        if (depth >= 10) return 'Keep every element at depth 10 or less.';
        stack.push([item, depth + 1]);
      } else if (!Number.isInteger(item) || item < -1000 || item > 1000) return 'arr holds only integers from -1000 to 1000 and arrays of them.';
    }
  }
  return null;
}

