function adapt(input, solve, kit) {
  const [arr, n] = input;
  // The problem asks for a solution without the built-in flat, so it is switched off during the call.
  const builtIn = Array.prototype.flat;
  Array.prototype.flat = function () { throw new Error('Solve it without the built-in Array.prototype.flat.'); };
  let result;
  try {
    result = solve(arr, n);
  } finally {
    Array.prototype.flat = builtIn;
  }
  if (!Array.isArray(result)) throw new Error('flat must return an array.');
  kit.trace(`flat(arr, ${n}) returns ${result.length} elements`);
  return result;
}

