function flat(arr, n) {
  // Flattening to depth n is the same as removing one level of brackets n times.
  let current = arr;
  for (let level = 0; level < n; level++) {
    const next = [];
    let opened = false;
    for (const item of current) {
      if (Array.isArray(item)) {
        for (const inner of item) next.push(inner);
        opened = true;
      } else next.push(item);
    }
    current = next;
    // Nothing left to open: later passes would change nothing.
    if (!opened) break;
  }
  return current;
}

