function generate(rand, size) {
  const small = size === 'small', maxDepth = small ? 4 : 10;
  let budget = small ? 10 : 6000;
  const number = () => rand() < 0.1 ? [-1000, 0, 1000][Math.floor(rand() * 3)] : Math.floor(rand() * (small ? 21 : 2001)) - (small ? 10 : 1000);
  // Items of the array built here sit at the given depth; only items above depth maxDepth may be arrays.
  const build = (depth, length) => {
    const items = [];
    for (let i = 0; i < length && budget > 0; i++) {
      budget--;
      if (depth < maxDepth && rand() < (small ? 0.35 : 0.12)) items.push(build(depth + 1, Math.floor(rand() * (small ? 4 : 12))));
      else items.push(number());
    }
    return items;
  };
  const arr = build(0, small ? Math.floor(rand() * 6) : 1500);
  if (!small) {
    // One chain that reaches the deepest allowed level.
    let chain = [number()];
    for (let depth = 9; depth > 0; depth--) chain = [chain];
    arr.splice(Math.floor(rand() * (arr.length + 1)), 0, chain);
  }
  const n = rand() < 0.15 ? 1000 : Math.floor(rand() * (small ? 5 : 12));
  return [arr, n];
}
